[InitializeOnLoad] public static class RewardRoomValidation {
 const string Flag="RewardRoomValidation";public const string Out="C:/Users/PC/Documents/Codex/RewardRooms-20261009/";static CollectionFlow flow;static double started;static int stage;static TowerRun run;static string[] ids;static ContentDatabase db;
 static RewardRoomValidation(){if(SessionState.GetBool(Flag,false))EditorApplication.update+=Tick;}
 public static void Run(){Environment.SetEnvironmentVariable("DRAGON_TOWER_TEST_SAVE","DragonTower.Test.RewardRooms");Directory.CreateDirectory(Out);SessionState.SetBool(Flag,true);EditorSceneManager.OpenScene("Assets/Scenes/Battle.unity");EditorApplication.EnterPlaymode();}
 static object Call(string n,params object[] a)=>typeof(CollectionFlow).GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(flow,a);
 static void Capture(string n)=>typeof(AugmentPresentationValidation).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{Out+n+".png"});
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
 static TowerRun Create(int floor,params TowerRoomKind[] choices){var d=flow.Session.Selected;var r=new TowerRun(d.maxHP,0,1,d.elementType,d.alternateSkillElement,d.StableId,d);r.AttachInstance(flow.Session.Profile.selectedInstanceId);var saved=r.Capture();saved.Floor=floor;saved.choices=choices;return TowerRun.Restore(saved,db);}
 static void VerifyCardText(){
 run=Create(1,TowerRoomKind.Item,TowerRoomKind.Augment);run.BeginFloorRoom(0,18421);SetRun();Call("ShowItemChoices");
 foreach(var item in db.items.Where(x=>x!=null)){var card=(Button)Call("ItemChoice",item,320f);var text=card.transform.Find("Reward summary").GetComponent<Text>();var settings=text.GetGenerationSettings(text.rectTransform.rect.size);float h=text.cachedTextGeneratorForLayout.GetPreferredHeight(text.text,settings)/text.pixelsPerUnit;Check(h<=text.rectTransform.rect.height+1,"item description overflow: "+item.displayName+" height "+h);UnityEngine.Object.DestroyImmediate(card.gameObject);}
 Debug.Log("REWARD_ITEM_TEXT_OK "+db.items.Length+" descriptions");
 }
 static void VerifySavedChest(){
 var r=Create(6,TowerRoomKind.Item,TowerRoomKind.Gold);r.BeginFloorRoom(0,78431);var selected=db.PickItems(3,r.RewardSeed^r.Floor).Select(x=>x.StableId).ToArray();r.OpenChest(selected);r.OpenChest(new[]{"must-not-replace"});Check(r.ChestRewardIds.SequenceEqual(selected),"chest cannot reroll");var saved=r.Capture();var copy=TowerRun.Restore(JsonUtility.FromJson<TowerRunSave>(JsonUtility.ToJson(saved)),db);Check(copy.ChestOpened&&copy.ChestRewardIds.SequenceEqual(selected),"saved chest IDs");var config=FloorProgressionConfig.Load();Check(copy.CompleteRoomEvent(config,0,50),"reward claim once");int experience=copy.Experience;Check(!copy.CompleteRoomEvent(config,99,99)&&copy.Experience==experience,"no duplicate EXP");var resume=TowerRun.Restore(copy.Capture(),db);Check(resume.EncounterDecided&&resume.AdditionalBattle==copy.AdditionalBattle&&resume.BattleExperiencePercent==copy.BattleExperiencePercent,"encounter and multiplier not rerolled");copy=TowerRun.Restore(saved,db);copy.CompleteRoomEvent(config,100,50);copy.MoveToNextFloor(0,1);Check(!copy.ChestOpened&&copy.ChestRewardIds==null,"new floor resets chest");saved.ChestOpened=false;saved.ChestRewardIds=null;Check(!TowerRun.Restore(saved,db).ChestOpened,"old save compatible");Debug.Log("REWARD_ROOM_SAVE_OK");
 }
