 if(flow==null){flow=UnityEngine.Object.FindFirstObjectByType<CollectionFlow>();if(flow?.Session==null){flow=null;return;}if(flow.Session.Selected==null)flow.Session.Hatch(0);db=ContentDatabase.Load();VerifySavedChest();VerifyCardText();run=Create(9,TowerRoomKind.Item,TowerRoomKind.Augment);SetRun();Call("ShowTowerChoices");Capture("stairs-two-doors");flow.RoomButton.onClick.Invoke();int seed=run.RewardSeed;flow.SecondRoomButton.onClick.Invoke();Check(run.Room==TowerRoomKind.Item&&run.Floor==9&&run.RewardSeed==seed,"duplicate door input blocked");started=EditorApplication.timeSinceStartup;return;}
 double t=EditorApplication.timeSinceStartup-started;
 if(stage==0&&t>2){Check(flow.ScreenName=="아이템방","door transition destination");flow.RoomButton.onClick.Invoke();Call("ShowLobby");flow.ResumeRun();Check(flow.ScreenName=="아이템 선택"&&flow.CurrentRun.ChestOpened,"actual lobby resume after opening");Capture("resumed-rewards");var claimed=flow.CurrentRun;var selectedButton=flow.ChoiceButtons[0];selectedButton.onClick.Invoke();Check(claimed.RewardClaimed,"item click completes reward");int total=claimed.ItemSlots.Count+claimed.ItemCountAt(3);Check(total==1,"exactly one item granted");selectedButton.onClick.Invoke();Check(claimed.ItemSlots.Count+claimed.ItemCountAt(3)==total,"repeat click no duplicate item");Call("ShowLobby");flow.ResumeRun();Check(flow.CurrentRun.ItemSlots.Count+flow.CurrentRun.ItemCountAt(3)==total,"claimed item persisted on resume");run=Create(10,TowerRoomKind.Boss);SetRun();Call("ShowTowerChoices");Capture("stairs-boss-door");flow.RoomButton.onClick.Invoke();Call("ShowLobby");flow.ResumeRun();Check(flow.ScreenName=="보스 전투"&&flow.CurrentRun.Floor==10,"boss selection resume");
 run=Create(4,TowerRoomKind.Gold,TowerRoomKind.Monster);SetRun();Call("ShowTowerChoices");Capture("stairs-gold-monster");flow.RoomButton.onClick.Invoke();Call("ShowLobby");flow.ResumeRun();Check(flow.ScreenName=="골드방"&&flow.CurrentRun.Floor==4,"room selection interrupted resume");
 Debug.Log("REWARD_PHASE_C_OK door double input blocked unchanged floor chest actual lobby resume boss resume room selection resume item selection duplicate prevention");run=Create(5,TowerRoomKind.Augment,TowerRoomKind.Item);run.BeginFloorRoom(0,58421);SetRun();Call("ShowAugmentChoices",false);started=EditorApplication.timeSinceStartup;stage=1;return;}
 if(stage==1&&t>1.5){Check(flow.RewardsReady,"augment reveal completes");flow.ChoiceButtons[0].onClick.Invoke();var confirm=GameObject.Find("이 선택으로 성장");Check(confirm!=null,"detail confirmation");confirm.GetComponent<Button>().onClick.Invoke();Check(run.RewardClaimed,"augment selection commits");run=Create(5,TowerRoomKind.Augment,TowerRoomKind.Item);run.BeginFloorRoom(0,58422);SetRun();Call("ShowAugmentChoices",false);started=EditorApplication.timeSinceStartup;stage=2;return;}
 if(stage==2&&t>1.5){Check(flow.RewardsReady,"skip unlocked after reveal");flow.SecondRoomButton.onClick.Invoke();Check(run.RewardClaimed&&run.Augments.Count==0,"augment skip without grant");Debug.Log("REWARD_SELECTION_OK item grant resume duplicate click augment detail confirm skip");SessionState.SetBool(Flag,false);EditorApplication.Exit(0);stage=3;}
 }catch(Exception e){Debug.LogException(e);SessionState.SetBool(Flag,false);EditorApplication.Exit(1);}}
 static void SetRun()=>typeof(CollectionFlow).GetField("towerRun",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(flow,run);
